// #95ffe2 API נתוני מגמות ודשבורד — аккаунт pregnancy (eat_healthier, главная метрика protein, kcal не показывается). Только чтение.
import { test, expect, BrowserContext, Page } from '@playwright/test';
import { openAs, saveSession, getTrends, getGoal, ok, rest, todayIn, expectInvariants, rangeCases } from './_trends';

test.describe.configure({ mode: 'serial' });
// Встроенный Chromium Playwright на этой машине не запускается (context.md) — установленный Google Chrome.
test.use({ channel: 'chrome' });

test.describe('trends API — pregnancy (protein)', () => {
  let ctx: BrowserContext;
  let page: Page;
  let today: string;

  test.beforeAll(async ({ browser }) => {
    ({ ctx, page } = await openAs(browser, 'pregnancy'));
    today = await todayIn(page);
  });
  test.afterAll(async () => {
    if (ctx) await saveSession(ctx, page, 'pregnancy');
  });

  test('метрики по профилю: protein первым, без kcal; home начинается с protein #95ffe2 @desktop @prod-safe', async () => {
    // AC2: метрики по профилю и целям (у pregnancy набор ≠ noa); AC3: target = личная цель; AC4: home ≤ 2.
    const { goal, keyMetrics } = await getGoal(page);
    expect(goal, 'у pregnancy есть цель').not.toBeNull();
    expect(goal.primary, 'главная метрика — protein').toBe('protein');
    const last = await rest(page, 'GET', `rest/v1/daily_totals?select=local_date&local_date=lte.${today}&order=local_date.desc&limit=1`);
    expect(last.status).toBe(200);
    expect(last.body.length, 'предусловие: у pregnancy есть хотя бы один день с едой').toBe(1);
    const date = last.body[0].local_date as string;

    const t = ok(await getTrends(page, { kind: 'day', date }), `day ${date}`);
    expectInvariants(t, `pregnancy/day ${date}`);
    expect(t.enoughData).toBe(true);
    const keys = t.metrics.map((m) => m.key);
    expect(keys, 'метрики = ключевые метрики профиля с целью').toEqual(keyMetrics.filter((k) => Number(goal.targets?.[k]) > 0));
    expect(keys[0], 'первая — protein').toBe('protein');
    expect(keys, 'kcal не входит в метрики pregnancy').not.toContain('kcal');
    for (const m of t.metrics) expect(m.target, `target ${m.key} = цель профиля`).toBe(goal.targets[m.key]);
    expect(t.home.length).toBeGreaterThanOrEqual(1);
    expect(t.home.length).toBeLessThanOrEqual(2);
    expect(t.home[0].key, 'home[0] — protein').toBe('protein');
    expect(t.home.map((h) => h.key)).not.toContain('kcal');
  });

  test('все диапазоны: инварианты ответа и нет kcal #95ffe2 @desktop @prod-safe', async () => {
    // AC1 + AC3/AC5/AC6/AC7 на другом профиле.
    for (const c of rangeCases(today)) {
      const t = ok(await getTrends(page, c.range), c.name);
      expect(t.range, `${c.name}: range`).toMatchObject({ from: c.from, to: c.to, days: c.days });
      expectInvariants(t, `pregnancy/${c.name}`);
      expect(t.metrics.map((m) => m.key), `${c.name}: без kcal`).not.toContain('kcal');
    }
  });
});
